-- P99-reviewed Velious content. Quest faction gates deliberately bypassed; actual faction rewards retained.
local item_lib = require("items")

function event_say(e)
  if e.message:findi("hail") then
    e.self:Emote("shivers and growls to itself.")
    e.self:Say("Much thanks must I give, " .. e.other:GetCleanName() .. ". Furless one still wants magic thing, after all the troubles? Say quickly. Much pain from attack. Must go, shaman help.")
  elseif e.message:findi("magic thing") then
    e.other:SummonItem(30042)
    eq.stop_timer("despawn")
    eq.depop()
  end
end

function event_spawn(e)
    eq.set_timer("despawn", 40000)
end

function event_timer(e)
  if e.timer == "despawn" then
    eq.stop_timer("despawn")
    eq.depop()
  end
end
